 1→import { OTA_AUTO_CHECK_STORAGE_KEY } from "./constants";
 2→
 3→const isLikelyIosWebView = () => {
 4→  if (typeof window === "undefined") {
 5→    return false;
 6→  }
 7→  const { userAgent, platform, maxTouchPoints } = window.navigator;
 8→  return /iPad|iPhone|iPod/.test(userAgent) || (platform === "MacIntel" && maxTouchPoints > 1);
 9→};
10→
11→const getOtaAutoCheckEnabled = () => {
12→  if (typeof window === "undefined") {
13→    return true;
14→  }
15→  return window.localStorage.getItem(OTA_AUTO_CHECK_STORAGE_KEY) !== "false";
16→};
17→
18→const statusEl = document.getElementById("ota-status");
19→const setStatus = (message: string) => {
20→  if (statusEl) {
21→    statusEl.textContent = message;
22→  }
23→};
24→
25→const mountBundledApp = async () => {
26→  const { mountApp } = await import("./mainApp");
27→  mountApp();
28→};
29→
30→const startWithOta = async () => {
31→  setStatus("Checking for updates...");
32→  const { prepare, start } = await import("@inkibra/tauri-plugin-ota");
33→  const manifestUrl = import.meta.env.VITE_OTA_MANIFEST_URL?.trim();
34→
35→  if (manifestUrl) {
36→    try {
37→      await prepare(manifestUrl);
38→    } catch (error) {
39→      console.warn("[OTA] prepare failed; falling back to bundled app", error);
40→    }
41→  } else {
42→    console.info("[OTA] VITE_OTA_MANIFEST_URL not set; using bundled app");
43→  }
44→
45→  setStatus("Starting app...");
46→  await start();
47→};
48→
49→const bootstrap = async () => {
50→  if (!isLikelyIosWebView()) {
51→    await mountBundledApp();
52→    return;
53→  }
54→
55→  if (!getOtaAutoCheckEnabled()) {
56→    setStatus("Starting bundled app...");
57→    await mountBundledApp();
58→    return;
59→  }
60→
61→  try {
62→    await startWithOta();
63→  } catch (error) {
64→    console.error("[OTA] startup failed; mounting bundled app directly", error);
65→    setStatus("Unable to load update. Starting bundled app...");
66→    await mountBundledApp();
67→  }
68→};
69→
70→void bootstrap();
71→

