 14→export type SettingsSectionId =
 15→  | "general"
 16→  | "profile"
 17→  | "sync"
 18→  | "updates"
 19→  | "appearance"
 20→  | "recordings"
 21→  | "security";
 22→type SettingsSection = {
 23→  id: SettingsSectionId;
 24→  title: string;
 25→};
 26→
 27→const SETTINGS_SECTIONS: SettingsSection[] = [
 28→  { id: "general", title: "General" },
 29→  { id: "profile", title: "Profile" },
 30→  { id: "sync", title: "Sync" },
 31→  { id: "updates", title: "Updates" },
 32→  { id: "appearance", title: "Appearance" },
 33→  { id: "recordings", title: "Recordings" },
 34→  { id: "security", title: "Security" },
 35→];
