 37→const shouldIgnorePaneFocusClick = (target: EventTarget | null) => {
 38→  if (!(target instanceof HTMLElement)) {
 39→    return false;
 40→  }
 41→  return Boolean(
 42→    target.closest("input, textarea, select, button, a, label, [contenteditable='true']")
 43→  );
 44→};
 45→
 46→function SettingsRow({
 47→  section,
 48→  isSelected,
 49→  onSelect,
 50→}: {
 51→  section: SettingsSection;
 52→  isSelected: boolean;
 53→  onSelect: () => void;
 54→}) {
 55→  return (
 56→    <Button
 57→      type="button"
 58→      className={`item-row settings-row${isSelected ? " selected" : ""}`}
 59→      variant="ghost"
 60→      size="sm"
 61→      onClick={onSelect}
 62→    >
 63→      <div className="settings-row-main">
 64→        <div className="settings-row-title">{section.title}</div>
 65→      </div>
 66→    </Button>
 67→  );
 68→}
 69→
 70→function SettingsDetail({ sectionId }: { sectionId: SettingsSectionId }) {
 71→  if (sectionId === "general") return <SettingsGeneralSection />;
 72→  if (sectionId === "profile") return <SettingsProfileSection />;
 73→  if (sectionId === "sync") return <SettingsSyncSection />;
 74→  if (sectionId === "updates") return <SettingsUpdatesSection />;
 75→  if (sectionId === "appearance") return <SettingsAppearanceSection />;
 76→  if (sectionId === "recordings") return <SettingsRecordingsSection />;
 77→  if (sectionId === "security") return <SettingsSecuritySection />;
 78→  return null;
 79→}
 80→
 81→export function SettingsMiddlePane({
 82→  activeSection,
 83→  onSectionChange,
 84→  middlePaneRef,
 85→  onPaneClick,
 86→}: {
 87→  activeSection: string;
 88→  onSectionChange: (id: SettingsSectionId) => void;
 89→  middlePaneRef: React.RefObject<HTMLDivElement | null>;
 90→  onPaneClick: () => void;
