 98→        tabIndex={0}
 99→        onClick={(event) => {
100→          if (shouldIgnorePaneFocusClick(event.target)) {
101→            return;
102→          }
103→          onPaneClick();
104→        }}
105→      >
106→        <nav className="settings-nav-list" aria-label="Settings sections">
107→          {SETTINGS_SECTIONS.map((section) => (
108→            <SettingsRow
109→              key={section.id}
110→              section={section}
111→              isSelected={activeSection === section.id}
112→              onSelect={() => onSectionChange(section.id)}
113→            />
114→          ))}
115→        </nav>
116→      </div>
117→    </div>
