  9→import { EditorProvider, useEditor } from "./contexts/EditorContext";
 10→import { NotesTreeProvider, useNotesTree } from "./contexts/NotesTreeContext";
 11→import { RecordingsProvider } from "./contexts/RecordingsContext";
 12→import { HandwritingProvider } from "./contexts/HandwritingContext";
 13→import { SecurityProvider, useSecurity } from "./contexts/SecurityContext";
 14→import { AppShell } from "./AppShell";
 15→import { useLayoutMode } from "./mobile/useLayoutMode";
 16→import { SecurityLockScreen } from "./components/SecurityLockScreen";
 17→
 18→function AppInner() {
 19→  const notesTree = useNotesTree();
 20→  const selection = useSelection();
 21→  const editor = useEditor();
 22→  const layoutMode = useLayoutMode();
 23→  const handleCapturedNoteComplete = async (result: {
 24→    folder_path: string;
 25→    note_path: string;
 26→  }) => {
 27→    await notesTree.refreshTree();
 28→    selection.setSelectedFolders(new Set([result.folder_path]));
 29→    selection.setLastSelectedFolder(result.folder_path);
 30→    selection.setActiveFolder(result.folder_path);
 31→    selection.setSelectedNotes(new Set([result.note_path]));
 32→    selection.setLastSelectedNote(result.note_path);
 33→    selection.setActiveNote(result.note_path);
 34→    editor.clearDraft();
 35→  };
 36→
 37→  return (
 38→    <RecordingsProvider
 39→      activeFolder={selection.activeFolder}
 40→      layoutMode={layoutMode}
 41→      onRecordingComplete={handleCapturedNoteComplete}
 42→    >
 43→      <HandwritingProvider
 44→        activeFolder={selection.activeFolder}
 45→        layoutMode={layoutMode}
 46→        onHandwritingComplete={handleCapturedNoteComplete}
 47→      >
 48→        <AppShell />
 49→      </HandwritingProvider>
 50→    </RecordingsProvider>
 51→  );
 52→}
 53→
 54→function FlushSaveBridge({
 55→  flushSaveRef,
 56→}: {
 57→  flushSaveRef: React.RefObject<(() => Promise<void>) | null>;
 58→}) {
 59→  const { flushSave } = useEditor();
 60→  flushSaveRef.current = flushSave;
 61→  return null;
 62→}
 63→
 64→function UnlockedApp({
 65→  flushSaveRef,
 66→}: {
 67→  flushSaveRef: React.RefObject<(() => Promise<void>) | null>;
 68→}) {
 69→  return (
 70→    <ProfilesProvider flushSaveRef={flushSaveRef}>
 71→      <GitSyncProvider>
 72→        <SelectionProvider>
 73→          <EditorProvider>
 74→            <NotesTreeProvider>
 75→              <FlushSaveBridge flushSaveRef={flushSaveRef} />
 76→              <AppInner />
 77→            </NotesTreeProvider>
 78→          </EditorProvider>
 79→        </SelectionProvider>
 80→      </GitSyncProvider>
 81→    </ProfilesProvider>
 82→  );
 83→}
 84→
 85→function SecurityGate({
 86→  flushSaveRef,
 87→}: {
 88→  flushSaveRef: React.RefObject<(() => Promise<void>) | null>;
 89→}) {
 90→  const {
 91→    securityState,
 92→    securityBusy,
 93→    securityError,
 94→    isLocked,
 95→    unlockSecurity,
 96→  } = useSecurity();
 97→
 98→  if (!securityState) {
 99→    return <div className="security-lock-screen">Loading security...</div>;
100→  }
101→
102→  if (securityState.encryption_enabled && isLocked) {
103→    return (
104→      <SecurityLockScreen
105→        busy={securityBusy}
106→        error={securityError}
107→        onUnlock={async (password) => {
108→          const result = await unlockSecurity(password);
109→          if (!result.unlocked) {
110→            return;
111→          }
112→        }}
113→      />
114→    );
115→  }
116→
117→  return <UnlockedApp flushSaveRef={flushSaveRef} />;
118→}
119→
120→function App() {
121→  const flushSaveRef = useRef<(() => Promise<void>) | null>(null);
122→
123→  return (
124→    <ThemeProvider>
125→      <SecurityProvider>
126→        <SecurityGate flushSaveRef={flushSaveRef} />
127→      </SecurityProvider>
128→    </ThemeProvider>
129→  );
130→}
131→
132→export default App;
