251→      if (start !== -1 && end !== -1) {
252→        const [from, to] = start < end ? [start, end] : [end, start];
253→        nextSelected.clear();
254→        visibleFolders.slice(from, to + 1).forEach((p) => nextSelected.add(p));
255→      } else {
256→        nextSelected.clear();
257→        nextSelected.add(path);
258→      }
259→    } else if (event.metaKey || event.ctrlKey) {
260→      if (nextSelected.has(path)) nextSelected.delete(path);
261→      else nextSelected.add(path);
262→    } else {
263→      nextSelected.clear();
264→      nextSelected.add(path);
265→    }
266→    setSelectedFolders(nextSelected);
267→    setLastSelectedFolder(path);
268→    setActiveFolder(path);
269→    setSelectedNotes(new Set());
270→    setLastSelectedNote("");
271→    setActiveNote(null);
272→    focusNoScroll(foldersPanelRef.current);
273→  };
