622→// Helper needed for note click handler
623→function findNodeInTree(node: import("./types").FolderNode, path: string): import("./types").FolderNode | null {
624→  if (node.path === path) return node;
625→  for (const child of node.children) {
626→    const found = findNodeInTree(child, path);
627→    if (found) return found;
628→  }
629→  return null;
630→}
