 31→export function DesktopRightPane({
 32→  appMode,
 33→  activeSettingsSection,
 34→}: DesktopRightPaneProps) {
 35→  const { activeNote, selectedNotes } = useSelection();
 36→  const [isLensPinned, setIsLensPinned] = useState(false);
 37→  const [isLensMenuOpen, setIsLensMenuOpen] = useState(false);
 38→  const {
 39→    noteContent,
 40→    draftNoteContent,
 41→    handleEditorChange,
 42→    flushSave,
 43→    rightPaneRef,
 44→  } = useEditor();
 45→  const { notes, notePreviews, allNotePreviews } = useNotesTree();
 46→
 47→  const selectedNotePaths = useMemo(() => {
 48→    const orderedByMiddleList = notes
 49→      .map((note) => note.path)
 50→      .filter((path) => selectedNotes.has(path));
 51→    const remainingSelected = Array.from(selectedNotes).filter(
 52→      (path) => !orderedByMiddleList.includes(path)
 53→    );
 54→    const mergedSelection = [...orderedByMiddleList, ...remainingSelected];
 55→    if (mergedSelection.length > 0) {
 56→      return mergedSelection;
 57→    }
 58→    return activeNote ? [activeNote] : [];
 59→  }, [activeNote, notes, selectedNotes]);
 60→
 61→  useEffect(() => {
 62→    if (selectedNotes.size > 1) {
 63→      setIsLensPinned(true);
 64→    }
 65→  }, [selectedNotes]);
 66→
 67→  const shouldShowLens = selectedNotePaths.length > 1 || isLensPinned;
 68→
 69→  const lensNotes = useMemo(
 70→    () =>
 71→      selectedNotePaths.map((path) => {
 72→        const preview = notePreviews[path] || allNotePreviews[path];
 73→        return {
 74→          path,
 75→          title: preview?.title || path.split("/").pop()?.replace(/\.md$/i, "") || path,
 76→          dateLabel: preview?.dateLabel || "",
 77→          isRecording: Boolean(preview?.isRecording),
 78→          transcriptionStatus: preview?.transcriptionStatus || null,
 79→        };
 80→      }),
 81→    [allNotePreviews, notePreviews, selectedNotePaths]
 82→  );
 83→
 84→  const activeNotePreview = activeNote
 85→    ? notePreviews[activeNote] || allNotePreviews[activeNote]
 86→    : undefined;
 87→  const editorMarkdown =
 88→    activeNote && activeNotePreview?.isRecording
 89→      ? sanitizeRecordingEditorContent(noteContent, activeNotePreview.transcriptionStatus)
 90→      : activeNote
 91→        ? noteContent
 92→        : draftNoteContent;
 93→
 94→  if (appMode === "notes") {
 95→    return (
 96→      <div className="pane editor-pane min-w-0">
 97→        <div
 98→          className="pane-body editor-body"
