107→                ".tiptap-content[contenteditable='true']"
108→              ) || rightPaneRef.current;
109→            focusNoScroll(editorElement);
110→          }}
111→        >
112→          {shouldShowLens ? (
113→            <MultiNoteLens
114→              notes={lensNotes}
115→              activeNote={activeNote}
116→              onBeforePersist={flushSave}
117→              onActiveNoteContentSync={(nextMarkdown) => {
118→                if (activeNote) {
119→                  handleEditorChange(nextMarkdown);
120→                }
121→              }}
122→              onExitLens={selectedNotePaths.length > 1 ? undefined : () => setIsLensPinned(false)}
123→            />
124→          ) : (
125→            <div className="editor-single">
126→              <div className="editor-top-row">
127→                {selectedNotePaths.length > 0 ? (
128→                  <div className="editor-lens-menu-area">
129→                    <DropdownMenu open={isLensMenuOpen} onOpenChange={setIsLensMenuOpen}>
130→                      <DropdownMenuTrigger asChild>
131→                        <button
132→                          type="button"
133→                          className="editor-lens-menu-trigger"
134→                          aria-label="Open editor menu"
135→                        >
136→                          <Menu aria-hidden="true" />
137→                        </button>
138→                      </DropdownMenuTrigger>
139→                      <DropdownMenuContent align="end">
140→                        <DropdownMenuItem onClick={() => setIsLensPinned(true)}>
141→                          Open Lens
142→                        </DropdownMenuItem>
143→                      </DropdownMenuContent>
144→                    </DropdownMenu>
145→                  </div>
146→                ) : null}
147→              </div>
148→              <RecordingNoteHeader notePath={activeNote} preview={activeNotePreview} />
149→              <HandwritingNoteHeader notePath={activeNote} preview={activeNotePreview} />
150→              <NoteEditor
151→                markdown={editorMarkdown}
152→                onChange={handleEditorChange}
153→              />
154→            </div>
155→          )}
156→        </div>
157→      </div>
158→    );
159→  }
160→
161→  return (
162→    <SettingsDetailPane
163→      activeSection={activeSettingsSection}
164→      onPaneClick={() => focusNoScroll(rightPaneRef.current)}
165→    />
166→  );
