 11→    isSecurityEnabled,
 12→    enableSecurity,
 13→    lockSecurity,
 14→    setAutoLockOnBackground,
 15→  } = useSecurity();
 16→  const [unlockPassword, setUnlockPassword] = useState("");
 17→  const [unlockConfirm, setUnlockConfirm] = useState("");
 18→  const [panicPassword, setPanicPassword] = useState("");
 19→  const [panicConfirm, setPanicConfirm] = useState("");
 20→  const [formError, setFormError] = useState<string | null>(null);
 21→
 22→  const canEnable = useMemo(() => {
 23→    return (
 24→      unlockPassword.trim().length > 0 &&
 25→      panicPassword.trim().length > 0 &&
 26→      unlockConfirm.trim().length > 0 &&
 27→      panicConfirm.trim().length > 0 &&
 28→      !securityBusy
 29→    );
 30→  }, [panicConfirm, panicPassword, securityBusy, unlockConfirm, unlockPassword]);
 31→
 32→  const onEnable = async () => {
 33→    if (unlockPassword !== unlockConfirm) {
 34→      setFormError("Unlock password confirmation does not match.");
 35→      return;
 36→    }
 37→    if (panicPassword !== panicConfirm) {
 38→      setFormError("Panic password confirmation does not match.");
 39→      return;
 40→    }
 41→    if (unlockPassword === panicPassword) {
 42→      setFormError("Unlock and panic passwords must be different.");
 43→      return;
 44→    }
 45→    setFormError(null);
 46→    try {
 47→      await enableSecurity(unlockPassword, panicPassword);
 48→      setUnlockPassword("");
 49→      setUnlockConfirm("");
 50→      setPanicPassword("");
 51→      setPanicConfirm("");
 52→    } catch {
 53→      return;
 54→    }
