 67→            <label className="grid gap-2 text-sm">
 68→              <span className="text-sm font-medium text-foreground">Unlock password</span>
 69→              <Input
 70→                type="password"
 71→                value={unlockPassword}
 72→                onChange={(event) => setUnlockPassword(event.target.value)}
 73→                autoCapitalize="off"
 74→                autoCorrect="off"
 75→              />
 76→            </label>
 77→            <label className="grid gap-2 text-sm">
 78→              <span className="text-sm font-medium text-foreground">Confirm unlock password</span>
 79→              <Input
 80→                type="password"
 81→                value={unlockConfirm}
 82→                onChange={(event) => setUnlockConfirm(event.target.value)}
 83→                autoCapitalize="off"
 84→                autoCorrect="off"
 85→              />
 86→            </label>
 87→            <label className="grid gap-2 text-sm">
 88→              <span className="text-sm font-medium text-foreground">Panic password</span>
 89→              <Input
 90→                type="password"
 91→                value={panicPassword}
 92→                onChange={(event) => setPanicPassword(event.target.value)}
 93→                autoCapitalize="off"
 94→                autoCorrect="off"
 95→              />
 96→            </label>
 97→            <label className="grid gap-2 text-sm">
 98→              <span className="text-sm font-medium text-foreground">Confirm panic password</span>
 99→              <Input
100→                type="password"
101→                value={panicConfirm}
102→                onChange={(event) => setPanicConfirm(event.target.value)}
103→                autoCapitalize="off"
104→                autoCorrect="off"
105→              />
106→            </label>
107→            <div className="flex flex-wrap gap-2">
108→              <Button size="sm" type="button" disabled={!canEnable} onClick={() => void onEnable()}>
109→                {securityBusy ? "Enabling..." : "Enable encryption"}
110→              </Button>
111→            </div>
112→            <p className="text-xs text-muted-foreground">
