117→          </section>
118→        ) : (
119→          <section className="space-y-3 rounded-lg border border-border/70 bg-card/30 p-4">
120→            <h3 className="text-sm font-semibold text-foreground">Protection</h3>
121→            <label className="inline-flex items-center gap-2 text-sm text-foreground">
122→              <input
123→                type="checkbox"
124→                checked={Boolean(securityState?.auto_lock_on_background)}
125→                disabled={securityBusy}
126→                onChange={(event) => {
