143→              </Button>
144→            </div>
145→            <p className="text-xs text-muted-foreground">
146→              Panic password entered on lock screen wipes local data, resets settings, and creates 3
147→              dummy notes.
148→            </p>
149→            {securityError ? <p className="text-xs text-destructive">{securityError}</p> : null}
