 85→export const readProfileSyncStore = (): Record<string, Partial<ProfileSyncSettings>> => {
 86→  if (typeof window === "undefined") {
 87→    return {};
 88→  }
 89→  try {
 90→    const raw = window.localStorage.getItem(PROFILE_SYNC_STORAGE_KEY);
 91→    if (!raw) {
 92→      return {};
 93→    }
 94→    const parsed = JSON.parse(raw);
 95→    if (parsed && typeof parsed === "object") {
 96→      return parsed as Record<string, Partial<ProfileSyncSettings>>;
 97→    }
 98→  } catch {
 99→    return {};
100→  }
101→  return {};
102→};
