  99→async fn run_blocking_command<T, F>(operation: F) -> Result<T, String>
 100→where
 101→    T: Send + 'static,
 102→    F: FnOnce() -> Result<T, String> + Send + 'static,
 103→{
 104→    tauri::async_runtime::spawn_blocking(operation)
 105→        .await
 106→        .map_err(|error| error.to_string())?
 107→}
