 136→#[tauri::command]
 137→async fn connect_git_repo(
 138→    app: tauri::AppHandle,
 139→    args: ConnectGitArgs,
 140→) -> Result<GitSyncStatus, String> {
 141→    ensure_security_unlocked_for_app(&app)?;
 142→    run_blocking_command(move || connect_git_repo_blocking(app, args)).await
 143→}
 144→
 145→fn connect_git_repo_blocking(
 146→    app: tauri::AppHandle,
 147→    args: ConnectGitArgs,
 148→) -> Result<GitSyncStatus, String> {
 149→    ensure_security_unlocked_for_app(&app)?;
 150→    let root = ensured_notes_root(&app)?;
 151→    let repo = ensure_git_repo(&root)?;
 152→    prepare_bootstrap_worktree_for_sync(&root, &repo)?;
 153→    ensure_origin_remote(&repo, &args.remote_url)?;
 154→    let target_branch = resolve_target_branch(&repo, args.branch.clone());
 155→    switch_or_prepare_branch(&repo, &target_branch)?;
 156→    let fetched = match perform_fetch(
 157→        &repo,
 158→        &target_branch,
 159→        args.username.as_deref(),
 160→        args.password.as_deref(),
 161→    ) {
 162→        Ok(commit) => Some(commit),
 163→        Err(error) => {
 164→            let lower = error.to_lowercase();
 165→            if lower.contains("couldn't find remote ref") {
 166→                None
 167→            } else {
 168→                return Err(error);
 169→            }
 170→        }
 171→    };
 172→    if let Some(fetched_commit) = fetched {
 173→        let analysis = repo
 174→            .merge_analysis(&[&fetched_commit])
 175→            .map_err(map_git_error)?
 176→            .0;
 177→        if analysis.is_fast_forward() || analysis.is_up_to_date() {
 178→            fast_forward_to(&repo, &target_branch, &fetched_commit)?;
 179→        }
 180→    }
 181→    Ok(build_git_status(&root))
 182→}
