 190→fn git_pull_blocking(app: tauri::AppHandle, args: GitSyncArgs) -> Result<GitSyncStatus, String> {
 191→    ensure_security_unlocked_for_app(&app)?;
 192→    let root = ensured_notes_root(&app)?;
 193→    if !git_repo_initialized(&root) {
 194→        return Err("Repository is not initialized. Connect a remote first.".to_string());
 195→    }
 196→    let repo = open_repo(&root)?;
 197→    prepare_bootstrap_worktree_for_sync(&root, &repo)?;
 198→    if git_has_changes(&repo) {
 199→        return Err("Local changes detected. Push or commit before pulling.".to_string());
 200→    }
 201→    let target_branch = resolve_target_branch(&repo, args.branch.clone());
 202→    switch_or_prepare_branch(&repo, &target_branch)?;
 203→    let fetched = perform_fetch(
 204→        &repo,
 205→        &target_branch,
 206→        args.username.as_deref(),
 207→        args.password.as_deref(),
 208→    )?;
 209→    let (analysis, _) = repo.merge_analysis(&[&fetched]).map_err(map_git_error)?;
 210→    if analysis.is_up_to_date() {
 211→        return Ok(build_git_status(&root));
 212→    }
 213→    if analysis.is_fast_forward() {
 214→        fast_forward_to(&repo, &target_branch, &fetched)?;
 215→        return Ok(build_git_status(&root));
 216→    }
 217→    if analysis.is_normal() {
 218→        merge_fetched_commit(&repo, &target_branch, &fetched)?;
 219→        return Ok(build_git_status(&root));
 220→    }
 221→    Err("Pull failed because local and remote history could not be merged.".to_string())
 222→}
