 224→fn remote_push(
 225→    repo: &Repository,
 226→    branch: &str,
 227→    username: Option<&str>,
 228→    password: Option<&str>,
 229→) -> Result<(), String> {
 230→    let callbacks = build_callbacks(username, password);
 231→    let mut push_options = PushOptions::new();
 232→    push_options.remote_callbacks(callbacks);
 233→    let mut remote = repo.find_remote("origin").map_err(map_git_error)?;
 234→    remote
 235→        .connect_auth(
 236→            Direction::Push,
 237→            Some(build_callbacks(username, password)),
 238→            None,
 239→        )
 240→        .map_err(map_git_error)?;
 241→    remote
 242→        .push(
 243→            &[&format!("refs/heads/{0}:refs/heads/{0}", branch)],
 244→            Some(&mut push_options),
 245→        )
 246→        .map_err(map_git_error)?;
 247→    let mut local = repo
 248→        .find_branch(branch, git2::BranchType::Local)
 249→        .map_err(map_git_error)?;
 250→    local
 251→        .set_upstream(Some(&format!("origin/{}", branch)))
 252→        .map_err(map_git_error)?;
 253→    Ok(())
 254→}
