 262→fn git_push_blocking(app: tauri::AppHandle, args: GitPushArgs) -> Result<GitSyncStatus, String> {
 263→    ensure_security_unlocked_for_app(&app)?;
 264→    let root = ensured_notes_root(&app)?;
 265→    if !git_repo_initialized(&root) {
 266→        return Err("Repository is not initialized. Connect a remote first.".to_string());
 267→    }
 268→    let repo = open_repo(&root)?;
 269→    let target_branch = resolve_target_branch(&repo, args.branch.clone());
 270→    switch_or_prepare_branch(&repo, &target_branch)?;
 271→    let message = args
 272→        .message
 273→        .as_ref()
 274→        .map(|value| value.trim())
 275→        .filter(|value| !value.is_empty())
 276→        .unwrap_or("Sync notes");
 277→    let status_before_push = build_git_status(&root);
 278→    if !status_before_push.push_required {
 279→        return Ok(status_before_push);
 280→    }
 281→    let _ = commit_all_changes(&repo, message, &target_branch)?;
 282→    remote_push(
 283→        &repo,
 284→        &target_branch,
 285→        args.username.as_deref(),
 286→        args.password.as_deref(),
 287→    )?;
 288→    Ok(build_git_status(&root))
 289→}
