 468→fn stop_native_audio_recording(app: tauri::AppHandle) -> Result<RecordingAudioPayload, String> {
 469→    ensure_security_unlocked_for_app(&app)?;
 470→    #[cfg(target_os = "ios")]
 471→    {
 472→        let state = {
 473→            let mut guard = ios_native_recorder_state()
 474→                .lock()
 475→                .map_err(|_| "Native recorder state lock poisoned.".to_string())?;
 476→            guard
 477→                .take()
 478→                .ok_or_else(|| "Native audio recorder is not active.".to_string())?
 479→        };
 480→
 481→        unsafe {
 482→            let recorder = state.recorder_ptr as *mut Object;
 483→            let _: () = msg_send![recorder, stop];
 484→            let _: () = msg_send![recorder, release];
 485→        }
 486→        deactivate_ios_audio();
 487→
 488→        let audio_bytes = fs::read(&state.output_path).map_err(|error| error.to_string())?;
 489→        let _ = fs::remove_file(&state.output_path);
 490→        if audio_bytes.is_empty() {
 491→            return Err("Native recorder returned an empty audio file.".to_string());
 492→        }
 493→
 494→        return Ok(RecordingAudioPayload {
 495→            mime_type: state.mime_type,
 496→            audio_base64: BASE64.encode(audio_bytes),
 497→        });
 498→    }
 499→
 500→    #[cfg(not(target_os = "ios"))]
 501→    {
 502→        Err("Native iOS audio recorder is unavailable on this platform.".to_string())
 503→    }
 504→}
