 598→#[tauri::command]
 599→fn queue_recording_transcriptions(
 600→    app: tauri::AppHandle,
 601→    args: QueueRecordingsArgs,
 602→) -> Result<RecordingTranscriptionQueueResult, String> {
 603→    ensure_security_unlocked_for_app(&app)?;
 604→    let api_key = args.assembly_api_key.trim();
 605→    if api_key.is_empty() {
 606→        return Err("AssemblyAI API key is required.".to_string());
 607→    }
 608→
 609→    let root = ensured_notes_root(&app)?;
 610→    let recordings = collect_recording_notes(&root)?;
 611→    let active_recordings = active_transcription_note_paths();
 612→    let mut scanned = 0usize;
 613→    let mut skipped = 0usize;
 614→    let mut candidates = Vec::new();
 615→
 616→    for recording in recordings {
 617→        scanned += 1;
 618→        if !recording.audio_path.exists() {
 619→            let _ = update_recording_note_status(
 620→                &recording.note_path,
 621→                RECORDING_STATUS_FAILED,
 622→                Some("Audio file is missing.".to_string()),
 623→                None,
 624→                None,
 625→            );
 626→            skipped += 1;
 627→            continue;
 628→        }
 629→
 630→        let status = recording.status.as_str();
 631→        let is_active_recording = active_recordings.contains(&recording.note_rel);
 632→
 633→        if status == RECORDING_STATUS_COMPLETED {
 634→            skipped += 1;
 635→            continue;
 636→        }
 637→
 638→        if matches!(
 639→            status,
 640→            RECORDING_STATUS_QUEUED | RECORDING_STATUS_PROCESSING
 641→        ) && is_active_recording
 642→        {
 643→            skipped += 1;
 644→            continue;
 645→        }
 646→
 647→        update_recording_note_status(
 648→            &recording.note_path,
 649→            RECORDING_STATUS_QUEUED,
 650→            None,
 651→            None,
 652→            None,
 653→        )?;
 654→        candidates.push(QueuedTranscriptionJob {
 655→            note_rel: recording.note_rel,
 656→            note_path: recording.note_path,
 657→            audio_path: recording.audio_path,
 658→            api_key: api_key.to_string(),
 659→        });
 660→    }
 661→
 662→    let queued = {
 663→        let queue = transcription_queue_state();
 664→        let mut state = queue.lock().expect("transcription queue poisoned");
 665→        let mut added = 0usize;
 666→        for job in candidates {
 667→            if state.known_recordings.contains(&job.note_rel) {
 668→                continue;
 669→            }
 670→            state.known_recordings.insert(job.note_rel.clone());
 671→            state.pending.push_back(job);
 672→            added += 1;
 673→        }
 674→        added
 675→    };
 676→
 677→    spawn_transcription_worker_if_needed();
 678→
 679→    let in_flight = recording_queue_snapshot().in_flight;
 680→
 681→    Ok(RecordingTranscriptionQueueResult {
 682→        scanned,
 683→        queued,
 684→        skipped,
 685→        in_flight,
 686→    })
 687→}
