 930→#[tauri::command]
 931→fn move_items(
 932→    app: tauri::AppHandle,
 933→    items: Vec<String>,
 934→    destination: String,
 935→) -> Result<(), String> {
 936→    ensure_security_unlocked_for_app(&app)?;
 937→    let root = ensured_notes_root(&app)?;
 938→    println!(
 939→        "[move_items] root={} destination={}",
 940→        root.to_string_lossy(),
 941→        destination
 942→    );
 943→    let destination_path = resolve_path(&app, &destination)?;
 944→    println!(
 945→        "[move_items] destination_path={}",
 946→        destination_path.to_string_lossy()
 947→    );
 948→    if !destination_path.exists() {
 949→        return Err(format!(
 950→            "Destination folder does not exist: {}",
 951→            destination_path.to_string_lossy()
 952→        ));
 953→    }
 954→
 955→    let mut source_groups_folders: HashMap<PathBuf, Vec<String>> = HashMap::new();
 956→    let mut source_groups_notes: HashMap<PathBuf, Vec<String>> = HashMap::new();
 957→    let mut moved_folder_names = Vec::new();
 958→    let mut moved_note_names = Vec::new();
 959→
 960→    for item in items {
 961→        let source = resolve_path(&app, &item)?;
 962→        if is_system_folder_path(&root, &source) {
 963→            return Err(format!(
 964→                "Cannot move system folder: {}",
 965→                source.to_string_lossy()
 966→            ));
 967→        }
 968→        if !source.exists() {
 969→            return Err(format!(
 970→                "Source does not exist: {}",
 971→                source.to_string_lossy()
 972→            ));
 973→        }
 974→        let meta = fs::metadata(&source).map_err(|err| {
 975→            format!(
 976→                "Failed to read metadata for {}: {}",
 977→                source.to_string_lossy(),
 978→                err
 979→            )
 980→        })?;
 981→        let name = source
 982→            .file_name()
 983→            .and_then(|n| n.to_str())
 984→            .ok_or_else(|| "Invalid item name.".to_string())?
 985→            .to_string();
 986→        let parent = source
 987→            .parent()
 988→            .ok_or_else(|| "Missing parent folder.".to_string())?
 989→            .to_path_buf();
 990→
 991→        let target = destination_path.join(&name);
 992→        println!(
 993→            "[move_items] move {} -> {}",
 994→            source.to_string_lossy(),
 995→            target.to_string_lossy()
 996→        );
 997→        fs::rename(&source, &target).map_err(|err| {
 998→            format!(
 999→                "Move failed {} -> {}: {}",
1000→                source.to_string_lossy(),
1001→                target.to_string_lossy(),
1002→                err
1003→            )
1004→        })?;
1005→        if meta.is_dir() {
1006→            source_groups_folders
1007→                .entry(parent)
1008→                .or_default()
1009→                .push(name.clone());
1010→            moved_folder_names.push(name);
1011→        } else {
1012→            source_groups_notes
1013→                .entry(parent)
1014→                .or_default()
1015→                .push(name.clone());
1016→            moved_note_names.push(name);
1017→        }
1018→    }
1019→
1020→    for (parent, names) in source_groups_folders {
1021→        let rel = strip_root(&root, &parent);
1022→        let parent_path = resolve_path(&app, &rel)?;
1023→        update_order_remove(&parent_path, &names, true)?;
1024→    }
1025→
1026→    for (parent, names) in source_groups_notes {
1027→        let rel = strip_root(&root, &parent);
1028→        let parent_path = resolve_path(&app, &rel)?;
1029→        update_order_remove(&parent_path, &names, false)?;
1030→    }
1031→
1032→    let dest_rel = strip_root(&root, &destination_path);
1033→    let dest_full = resolve_path(&app, &dest_rel)?;
1034→    println!(
1035→        "[move_items] update order dest={} folders={} notes={}",
1036→        dest_full.to_string_lossy(),
1037→        moved_folder_names.len(),
1038→        moved_note_names.len()
1039→    );
1040→    if !moved_folder_names.is_empty() {
1041→        update_order_append(&dest_full, &moved_folder_names, true)?;
1042→    }
1043→    if !moved_note_names.is_empty() {
1044→        update_order_append(&dest_full, &moved_note_names, false)?;
1045→    }
1046→
1047→    Ok(())
1048→}
