1050→#[tauri::command]
1051→fn delete_items(app: tauri::AppHandle, items: Vec<String>) -> Result<(), String> {
1052→    ensure_security_unlocked_for_app(&app)?;
1053→    let root = ensured_notes_root(&app)?;
1054→    let mut parent_folder_groups: HashMap<PathBuf, Vec<String>> = HashMap::new();
1055→    let mut parent_note_groups: HashMap<PathBuf, Vec<String>> = HashMap::new();
1056→
1057→    for item in items {
1058→        let full_path = resolve_path(&app, &item)?;
1059→        if is_system_folder_path(&root, &full_path) {
1060→            return Err(format!(
1061→                "Cannot delete system folder: {}",
1062→                full_path.to_string_lossy()
1063→            ));
1064→        }
1065→        let name = full_path
1066→            .file_name()
1067→            .and_then(|n| n.to_str())
1068→            .ok_or_else(|| "Invalid item name.".to_string())?
1069→            .to_string();
1070→        let parent = full_path
1071→            .parent()
1072→            .ok_or_else(|| "Missing parent folder.".to_string())?
1073→            .to_path_buf();
1074→        let meta = fs::metadata(&full_path).map_err(|err| err.to_string())?;
1075→        if meta.is_dir() {
1076→            fs::remove_dir_all(&full_path).map_err(|err| err.to_string())?;
1077→            parent_folder_groups.entry(parent).or_default().push(name);
1078→        } else {
1079→            fs::remove_file(&full_path).map_err(|err| err.to_string())?;
1080→            parent_note_groups.entry(parent).or_default().push(name);
1081→        }
1082→    }
1083→
1084→    for (parent, names) in parent_folder_groups {
1085→        let rel = strip_root(&root, &parent);
1086→        let parent_path = resolve_path(&app, &rel)?;
1087→        update_order_remove(&parent_path, &names, true)?;
1088→    }
1089→
1090→    for (parent, names) in parent_note_groups {
1091→        let rel = strip_root(&root, &parent);
1092→        let parent_path = resolve_path(&app, &rel)?;
1093→        update_order_remove(&parent_path, &names, false)?;
1094→    }
1095→
1096→    Ok(())
1097→}
