 5→const isIosDevice = () => {
 6→  if (typeof window === "undefined") {
 7→    return false;
 8→  }
 9→  const { userAgent, platform, maxTouchPoints } = window.navigator;
10→  return /iPad|iPhone|iPod/.test(userAgent) || (platform === "MacIntel" && maxTouchPoints > 1);
11→};
12→
13→const lockIosZoom = () => {
14→  if (!isIosDevice()) {
15→    return;
16→  }
17→
18→  const viewportMeta = document.querySelector<HTMLMetaElement>("meta[name='viewport']");
19→  if (viewportMeta) {
20→    const contentTokens = viewportMeta.content
21→      .split(",")
22→      .map((token) => token.trim())
23→      .filter((token) => token.length > 0)
24→      .filter((token) => !/^(maximum-scale|minimum-scale|user-scalable)\s*=/.test(token));
25→    viewportMeta.content = [
26→      ...contentTokens,
27→      "maximum-scale=1",
28→      "minimum-scale=1",
29→      "user-scalable=no",
30→    ].join(", ");
31→  }
32→
33→  const preventGestureZoom = (event: Event) => {
34→    event.preventDefault();
35→  };
36→  const preventPinchZoom = (event: TouchEvent) => {
37→    if (event.touches.length > 1) {
38→      event.preventDefault();
39→    }
40→  };
41→  let lastTouchEndAt = 0;
42→  const preventDoubleTapZoom = (event: TouchEvent) => {
43→    const now = Date.now();
44→    if (now - lastTouchEndAt < 280) {
45→      event.preventDefault();
46→    }
47→    lastTouchEndAt = now;
48→  };
49→
50→  document.addEventListener("gesturestart", preventGestureZoom as EventListener);
51→  document.addEventListener("gesturechange", preventGestureZoom as EventListener);
52→  document.addEventListener("gestureend", preventGestureZoom as EventListener);
53→  document.addEventListener("touchstart", preventPinchZoom, { passive: false });
54→  document.addEventListener("touchmove", preventPinchZoom, { passive: false });
55→  document.addEventListener("touchend", preventDoubleTapZoom, { passive: false });
56→};
57→
58→export const mountApp = () => {
59→  lockIosZoom();
60→  const splash = document.getElementById("ota-splash");
61→  if (splash) {
62→    splash.remove();
63→  }
64→  ReactDOM.createRoot(document.getElementById("root") as HTMLElement).render(
65→    <React.StrictMode>
66→      <App />
67→    </React.StrictMode>,
68→  );
69→};
