      />
      <ChoiceRow
        label="Always use bundled version"
        subtitle="Skips OTA network check for faster startup."
        selected={!otaAutoCheckEnabled}
        onClick={() => {
          setLocalOtaAutoCheckEnabled(false);
          setOtaAutoCheckEnabled(false);
        }}
      />
    </Group>
  );
}

