  1→import { invoke } from '@tauri-apps/api/core';
  2→
  3→export enum UpdateStatus {
  4→  Ready = 'ready',
  5→  Error = 'error'
  6→}
  7→
  8→export type UpdateInfo = {
  9→  update?: string;
 10→  manifest?: {
 11→    version: string;
 12→    url: string;
 13→    hash: string;
 14→    notes?: string;
 15→  };
 16→  error?: string;
 17→}
 18→
 19→// Store for registered startup handlers
 20→let registeredStartupHandlers: Array<() => void | Promise<void>> = [];
 21→let updateInfo: UpdateInfo | undefined = undefined;
 22→let prepared = false;
 23→let started = false;
 24→
 25→/**
 26→ * Prepare the app by checking for updates and applying them if available
 27→ * @param manifestUrl URL to the update manifest JSON
 28→ * @returns Information about the update status including content if update is available
 29→ */
 30→export async function prepare(manifestUrl: string): Promise<UpdateInfo> {
 31→  if (prepared) {
 32→    throw new Error('App already prepared');
 33→  }
 34→  const result = await invoke<UpdateInfo>('plugin:ota|prepare', { 
 35→    payload: { manifestUrl } 
 36→  });
 37→  updateInfo = result;
 38→  prepared = true;
 39→  return result;
 40→}
 41→
 42→/**
 43→ * Start the app by loading the appropriate JavaScript file
 44→ * Using Blob for dynamic loading if update is available
 45→ * @param updateInfo Optional update info from prepare() call
 46→ */
 47→export async function start(): Promise<void> {
 48→  console.info('Starting app...');
 49→
 50→  if (!prepared) {
 51→    throw new Error('App not prepared');
 52→  }
 53→  if (started) {
 54→    throw new Error('App already started');
 55→  }
 56→  
 57→  // Check if we have an update
 58→  if (updateInfo?.update) {
 59→    console.info('Loading update from content...');
 60→    
 61→    // Create a blob from the update content
 62→    const blob = new Blob([updateInfo.update], { type: 'application/javascript' });
 63→    const scriptURL = URL.createObjectURL(blob);
 64→    
 65→    // Create script element
 66→    const script = document.createElement('script');
 67→    script.src = scriptURL;
 68→    script.async = true;
 69→    script.defer = true;
 70→    
 71→    // Clean up the URL when the script is loaded
 72→    script.onload = () => URL.revokeObjectURL(scriptURL);
 73→    
 74→    // Append to document
 75→    document.head.appendChild(script);
 76→  } else {
 77→    console.info('Loading default bundled script...');
 78→    
 79→    // Create script element for bundled app.js
 80→    const script = document.createElement('script');
 81→    script.src = './app.js';
 82→    script.async = true;
 83→    script.defer = true;
 84→    
 85→    // Append to document
 86→    document.head.appendChild(script);
 87→  }
 88→}
 89→
 90→/**
 91→ * Register a startup handler that will be called when the app starts
