      </span>
    </button>
  );
}

export function InputRow({
  label,
  value,
  onChange,
  placeholder,
  password,
  disabled,
}: {
  label: string;
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  password?: boolean;
  disabled?: boolean;
}) {
